'use strict';
// Engineer-facing preview. Production authorization must also be enforced by Django.
let engineerBucket='assigned',engineerSearch='';
const managerRender=render,baseOpenSite=openSite,baseGo=go,baseRole=changeRole,baseSectionLock=sectionLocked;
const assignedToEngineer=s=>!!s&&s.engineer==='Project engineer';
const engineerComplete=s=>['Awaiting review','Under Review','Approved'].includes(s.status);
const engineerEditable=s=>assignedToEngineer(s)&&!engineerComplete(s);
function engineerCanRead(s=site()){if(role!=='Engineer'||assignedToEngineer(s))return true;toast('This site is not assigned to you');return false;}
function engineerCanEdit(s=site()){if(role!=='Engineer')return true;if(!engineerCanRead(s))return false;if(!engineerEditable(s)){toast('Submitted surveys are read-only. Wait for returned corrections.');return false;}return true;}
sectionLocked=function(id,s=site()){return baseSectionLock(id,s)||(role==='Engineer'&&!engineerEditable(s));};
openSite=function(id,part='general'){const s=data.sites.find(x=>x.id===id);if(!s||!engineerCanRead(s))return;if(role!=='Engineer')return baseOpenSite(id,part);selected=id;section=part==='submission'?'submission':'general';customSection=part==='submission'?reviewSections(s).length:0;workTab='checklist';viewerIndex=0;view='workspace';render();window.scrollTo({top:0,behavior:'instant'});};
go=function(v){if(role==='Engineer'&&!['overview','sites','workspace'].includes(v)){toast('Your workspace contains assigned sites only');view='overview';render();return;}return baseGo(v);};
changeRole=function(r){if(!['Engineer','Team leader','Admin'].includes(r))return;role=r;view='overview';workTab='checklist';engineerBucket='assigned';reviewSelection.clear();reviewNote='';const ss=visibleSites();if(ss.length)selected=ss[0].id;render();};
for(const name of ['saveField','saveCheck','saveEquipment','addEquipment','removeEquipment','saveCustomAnswer','saveCustomInspection','addCustomTableRow','removeCustomTableRow','saveCustomTableCell','uploadForSite','submitSite']){const fn=globalThis[name];globalThis[name]=function(...args){if(!engineerCanEdit())return;return fn(...args);};}
for(const name of ['removePhoto','setPhotoCategory']){const fn=globalThis[name];globalThis[name]=function(id,...args){const s=data.sites.find(x=>x.id===id);if(!s||!engineerCanEdit(s))return;return fn(id,...args);};}
const originalDownloadReport=downloadReport;downloadReport=function(id){const s=data.sites.find(x=>x.id===id);if(!s||!engineerCanRead(s))return;return originalDownloadReport(id);};
const originalPrint=printReport;printReport=function(){if(engineerCanRead())return originalPrint();};
for(const name of ['newSite','createSite','resetDemo','newChecklistTemplate','tryTemplate','publishTemplate','assignChecklistTemplate','duplicateChecklistTemplate']){const fn=globalThis[name];globalThis[name]=function(...args){if(role==='Engineer'){toast('This action is managed by your project team');return;}return fn(...args);};}
function engineerSetBucket(b){engineerBucket=b;view='overview';render();}
function engineerHeader(){return `<header class="engineer-header"><a href="#" onclick="go('overview');return false" aria-label="iSurvix Survey home"><img src="assets/logo-latest.png" alt="iSurvix — Intelligent Survey Index"></a><span class="engineer-product">Field surveys</span><div class="engineer-identity">${I('users')}<div><strong>Project engineer</strong><small>Assigned sites only</small></div></div></header><div class="engineer-demo"><span>Sample data · Saved on this device</span><label>Preview role <select aria-label="Preview role" onchange="changeRole(this.value)">${['Engineer','Team leader','Admin'].map(r=>`<option ${role===r?'selected':''}>${r}</option>`).join('')}</select></label></div>`;}
function engineerDashboard(){const ss=visibleSites(),pending=ss.filter(x=>!engineerComplete(x)),complete=ss.filter(engineerComplete),filtered=(engineerBucket==='pending'?pending:engineerBucket==='complete'?complete:ss).filter(s=>(s.id+' '+s.location+' '+s.project).toLowerCase().includes(engineerSearch.toLowerCase()));return `<section class="engineer-title"><p class="engineer-eyebrow">MY FIELDWORK</p><h1>Your sites. Your next step.</h1><p>Open an assigned site, complete its checklist, and submit your survey.</p></section><nav class="engineer-buckets" aria-label="My site lists">${[['assigned','Assigned',ss.length],['pending','Pending',pending.length],['complete','Complete',complete.length]].map(([id,label,n])=>`<button aria-pressed="${engineerBucket===id}" class="${engineerBucket===id?'active':''}" onclick="engineerSetBucket('${id}')">${label}<span>${n}</span></button>`).join('')}</nav><form class="engineer-find" onsubmit="event.preventDefault();engineerSearch=this.querySelector('input').value;render()">${I('search')}<input aria-label="Search assigned sites" placeholder="Find an assigned Site ID or location…" value="${E(engineerSearch)}"><button class="btn" type="submit">Find site</button></form><div class="engineer-sites">${filtered.map(s=>`<article class="engineer-site"><div class="engineer-site-top"><div><small>${E(s.project)}</small><h2>${E(s.id)}</h2><p>${I('pin')}${E(s.location)} · ${E(s.type)}</p></div><span class="engineer-status ${engineerComplete(s)?'done':s.status==='Changes requested'||s.status==='Rejected'?'returned':''}">${E(s.status==='Awaiting review'?'Submitted':s.status==='Approved'?'Approved':s.status==='Changes requested'?'Corrections required':s.status==='Rejected'?'Returned — rejected':s.status==='Partially approved'?'Remaining sections pending':s.status)}</span></div><div class="engineer-site-bottom"><div><div class="engineer-progress-text"><span>${engineerComplete(s)?'Survey submitted':'Checklist progress'}</span><b>${s.progress}%</b></div><div class="progress"><span style="width:${s.progress}%"></span></div><small>${engineerComplete(s)?'Read-only copy · No action needed':s.status==='Changes requested'||s.status==='Rejected'?'Open the site to see feedback and update your survey':'Changes save as you work'}</small></div><button class="btn ${engineerComplete(s)?'':'primary'}" onclick="openSite('${E(s.id)}')">${engineerComplete(s)?'View submission':s.status==='Draft'?'Start survey':'Continue survey'}${I('arrow')}</button></div></article>`).join('')||'<div class="engineer-empty">'+I('check')+'<h2>No sites in this list</h2><p>Your project team will assign sites here. Try another list or search.</p></div>'}</div><p class="engineer-list-note">“Complete” contains submitted and approved surveys. Pending contains unfinished or returned work.</p>`;}
function engineerCurrentIndex(){const all=reviewSections();return site().templateSnapshot?Math.min(customSection,all.length):section==='submission'?all.length:Math.max(0,all.findIndex(x=>x.id===section));}
function engineerSection(i){const all=reviewSections();i=Math.max(0,Math.min(Number(i),all.length));if(site().templateSnapshot)customSection=i;else section=i===all.length?'submission':all[i].id;viewerIndex=0;render();window.scrollTo({top:0,behavior:'instant'});}
function engineerSubmission(){const s=site(),missing=missingItems(s),complete=engineerComplete(s);return `<section class="engineer-submit"><span class="engineer-submit-icon">${I(complete?'check':'upload')}</span><h2>${complete?'Survey submitted':'Submit your survey'}</h2><p>${complete?'Your survey has been sent to the project team. You can view your submitted answers and evidence.':'Check the required items below, then send your survey to the project team.'}</p><div class="submission-summary"><div><span>Checklist sections</span><b>${reviewSections().length}</b></div><div><span>Photographs</span><b>${s.photos.length}</b></div><div><span>Required items pending</span><b>${missing.length}</b></div></div>${!complete&&missing.length?`<div class="engineer-missing"><strong>Complete these before submitting</strong><ul>${missing.map(x=>`<li>${E(x)}</li>`).join('')}</ul></div>`:''}${!complete?`<button class="btn primary" ${missing.length?'disabled':''} onclick="submitSite()">${I('upload')}Submit survey</button><small class="engineer-submit-hint">After submission, your answers stay read-only until corrections are requested.</small>`:'<button class="btn" onclick="go(\'overview\')">Back to my sites</button>'}</section>`;}
function engineerWorkspace(){const s=site(),all=reviewSections(),i=engineerCurrentIndex(),sec=all[i],complete=engineerComplete(s),locked=sectionLocked(sec?.id,s);return `<button class="engineer-back" onclick="go('overview')">${I('back')}My sites</button><div class="engineer-work-heading"><div><small>${E(s.project)} · ${E(s.location)}</small><h1>${E(s.id)}</h1></div><span class="engineer-status ${complete?'done':''}">${E(complete?s.status==='Approved'?'Approved · read only':'Submitted · read only':s.status)}</span></div>${s.comments.length?`<details class="engineer-feedback" ${['Changes requested','Rejected'].includes(s.status)?'open':''}><summary>Project team feedback (${s.comments.length})</summary>${s.comments.map(c=>`<p><strong>${E(c.by)}</strong><br>${E(c.text)}</p>`).join('')}</details>`:''}${complete?'<div class="engineer-info">This is your submitted copy. Your project team handles approval.</div>':''}<div class="engineer-step"><div><span>${sec?'Section '+(i+1)+' of '+all.length:'Final step'}</span><b>${E(sec?.title||'Submit survey')}</b></div><select aria-label="Go to checklist section" onchange="engineerSection(this.value)">${all.map((x,j)=>`<option value="${j}" ${i===j?'selected':''}>${j+1}. ${E(x.title)}${sectionLocked(x.id,s)?' · Locked':''}</option>`).join('')}<option value="${all.length}" ${i===all.length?'selected':''}>${complete?'Submission summary':'Submit survey'}</option></select></div>${sec?`<div class="engineer-work-tabs"><button class="${workTab==='checklist'?'active':''}" onclick="setWorkTab('checklist')">${I('clipboard')}Checklist</button><button class="${workTab==='photos'?'active':''}" onclick="setWorkTab('photos')">${I('camera')}Photos</button><span id="save-state">${locked?'Read only':'Saved on this device'}</span></div>${workTab==='photos'?workspacePhotos():`<section class="engineer-form">${s.templateSnapshot?sec.fields.map(f=>customFieldMarkup(s,f,locked)).join(''):workspaceForm(s,locked)}</section>`}`:engineerSubmission()}<div class="engineer-step-footer"><button class="btn" ${i===0?'disabled':''} onclick="engineerSection(${i-1})">${I('back')}Back</button><span>${sec?(locked?'This section is read only':'Complete fields and add evidence'):'End of checklist'}</span>${i<all.length?`<button class="btn primary" onclick="engineerSection(${i+1})">${i===all.length-1?'Submission summary':'Next section'}${I('arrow')}</button>`:`<button class="btn" onclick="go('overview')">My sites</button>`}</div>`;}
render=function(){if(role!=='Engineer'){managerRender();return;}if(!['overview','sites','workspace'].includes(view))view='overview';if(view==='workspace'&&!assignedToEngineer(site()))view='overview';document.getElementById('app').innerHTML=`<div class="layout-v3 engineer-layout">${engineerHeader()}<main class="engineer-main ${view==='workspace'?'engineer-working':''}">${view==='workspace'?engineerWorkspace():engineerDashboard()}</main><footer class="engineer-footer">iSurvix Survey<span>Design preview · Backend integration pending</span></footer></div>`;};
// The approved review workspace is the default; Engineer remains a separate journey.
if(typeof location!=='undefined'&&location.hash==='#engineer'){role='Engineer';view='overview';selected=visibleSites()[0]?.id||selected;workTab='checklist';}
else if(typeof location==='undefined'||location.hash!=='#builder'){role='Team leader';view='workspace';selected=data.sites.find(s=>s.status==='Awaiting review')?.id||data.sites[0].id;section='civil';workTab='photos';catalogOpen=true;}
render();
